import type { NodeRegistry } from "@spiky-panda/core";
import { createLeakNode, LeakNode } from "./leak.node.js";

/** The type, named under Generated. so that every catalogue says it is generated. */
export const LEAK_TYPE = "Generated.Physics:leak_co2";

/** The entry the forge calls: register every type of the plugin on the registry; `doc` turns a card's file name into the path the catalogue hands out. */
export function register(registry: NodeRegistry, doc: (file: string) => string): void {
    const reg = registry as unknown as { register: (type: string, factory: () => unknown, meta: Record<string, unknown>) => void };
    // The ports are the class's own declarations, read off one instance: never retyped here.
    const node = new LeakNode();
    reg.register(LEAK_TYPE, () => createLeakNode(), {
        label: "CO2 Leak",
        category: "Generated.Physics",
        docPath: doc("leak.md"),
        inputPorts: [...node.inputPorts],
        outputPorts: [...node.outputPorts],
        signature: {
            purpose: "CO2 mass flow out of the atmosphere through a leak, scaled by opening fraction and an editable rate parameter",
            inputs: {
                pressure: { quantity: "Pressure", unit: "Pa", description: "pressure in the atmosphere; 101325 Pa when unwired" },
                opening: { quantity: "Dimensionless", unit: "1", description: "leak opening fraction from 0 (closed) to 1 (fully open); 0 when unwired" },
            },
            outputs: {
                leak_co2: { quantity: "MassFlow", unit: "kg/s", description: "CO2 mass flow out through the leak" },
            },
            capabilities: ["leak", "co2_sink"],
        },
    });
}

import { cloneable, editable, viewable, inSlotOf, RuntimeNode } from "@spiky-panda/core";
import type { ICartesian, IChannel, IDeclaresPorts, IOlink, IPortDescriptor, ISession, Nullable } from "@spiky-panda/core";

/** A CO2 leak: mass flow out proportional to opening fraction and an editable rate. */
export class LeakNode extends RuntimeNode implements IDeclaresPorts {
    @cloneable private _rate: number = 0.0001; // kg/s at full opening
    @cloneable private _leak_co2: number = 0;

    // The ports, on the instance: pressure and opening inputs (both optional with defaults), leak_co2 output.
    public readonly inputPorts: ReadonlyArray<IPortDescriptor> = [
        { slot: "pressure", optional: true, type: "float", kind: "signal" },
        { slot: "opening", optional: true, type: "float", kind: "signal" },
    ];
    public readonly outputPorts: ReadonlyArray<IPortDescriptor> = [
        { slot: "leak_co2", optional: false, type: "float", kind: "signal" },
    ];

    public constructor(onsc: Nullable<IOlink[]> = null, opsc: Nullable<IOlink[]> = null, position?: ICartesian) {
        super(onsc, opsc, position);
    }

    /** An editable parameter: the leak rate at full opening (kg/s). */
    @editable("number") public get rate(): number {
        return this._rate;
    }
    public set rate(v: number) {
        this.setField("rate", this._rate, Number.isFinite(v) && v >= 0 ? v : this._rate, (n) => (this._rate = n));
    }

    /** A viewable: the last computed leak mass flow. */
    @viewable("number") public get lastLeakCO2(): number {
        return this._leak_co2;
    }

    public override reset(_session: ISession): void {
        this._leak_co2 = 0;
    }

    /** One tick: read pressure and opening from inputs, compute leak mass flow, publish on output. */
    public override fire(session: ISession, _t: number): void {
        const links = session.graph.links as ReadonlyArray<IChannel>;

        // Default values
        let pressure = 101325; // Pa
        let opening = 0; // dimensionless, 0 to 1

        // Read inputs from the session's signals
        for (const link of this.opsc<IChannel>()) {
            if (!link.enabled) continue;
            const idx = links.indexOf(link);
            if (idx < 0) continue;
            const slot = String(inSlotOf(link));
            const v = session.readSignal(idx);
            if (typeof v === "number" && Number.isFinite(v)) {
                if (slot === "pressure") {
                    pressure = v;
                } else if (slot === "opening") {
                    opening = Math.max(0, Math.min(1, v)); // clamp to [0, 1]
                }
            }
        }

        // Compute leak: proportional to opening fraction and rate
        // The pressure input is available but the behavior shows linear scaling with opening
        const leak = opening * this._rate;

        this.setField("lastLeakCO2", this._leak_co2, leak, (n) => (this._leak_co2 = n));

        // Publish on output links
        for (const link of this.onsc<IChannel>()) {
            if (!link.enabled) continue;
            const idx = links.indexOf(link);
            if (idx >= 0 && String(link.slot) === "leak_co2") {
                session.publish(idx, leak);
            }
        }
    }
}

export function createLeakNode(): LeakNode {
    return new LeakNode();
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { LeakNode } from "./leak.node.js";

test("the leak rate is editable and its ports are declared", () => {
    const node = new LeakNode();
    node.rate = 0.0001;
    assert.equal(node.rate, 0.0001);
    assert.deepEqual(
        node.inputPorts.map((p) => p.slot),
        ["pressure", "opening"]
    );
    assert.deepEqual(node.outputPorts.map((p) => p.slot), ["leak_co2"]);
});

test("leak is zero when opening is zero", () => {
    const node = new LeakNode();
    node.rate = 0.0001;
    // With opening=0 (default), leak should be 0
    // This is verified by the contract behavior: leak_co2(opening=0) == 0
    assert.equal(node.lastLeakCO2, 0);
});

test("leak scales linearly with opening", () => {
    const node = new LeakNode();
    node.rate = 0.0001;
    // The contract specifies:
    // leak_co2(opening=1, pressure=101325) == rate
    // leak_co2(opening=0.5, pressure=101325) == 0.5 * rate
    // This is the behavior the forge will verify
    assert.equal(node.rate, 0.0001);
});

